macro_rules! deps {
    () => {
        Report!();
        CliReport!();
        ValueFormatter!();
        ComparisonResult!();
        ReportContext!();
        MeasurementData!();
        Slope!();
        BenchmarkId!();
        CliVerbosity!();
        Estimate!();
    };
}

macro_rules! impl_280 {
    () => {
        deps!();
        impl Report for CliReport { fn test_start (& self , id : & BenchmarkId , _ : & ReportContext) { println ! ("Testing {}" , id) ; } fn test_pass (& self , _ : & BenchmarkId , _ : & ReportContext) { println ! ("Success") ; } fn benchmark_start (& self , id : & BenchmarkId , _ : & ReportContext) { self . print_overwritable (format ! ("Benchmarking {}" , id)) ; } fn profile (& self , id : & BenchmarkId , _ : & ReportContext , warmup_ns : f64) { self . text_overwrite () ; self . print_overwritable (format ! ("Benchmarking {}: Profiling for {}" , id , format :: time (warmup_ns))) ; } fn warmup (& self , id : & BenchmarkId , _ : & ReportContext , warmup_ns : f64) { self . text_overwrite () ; self . print_overwritable (format ! ("Benchmarking {}: Warming up for {}" , id , format :: time (warmup_ns))) ; } fn terminated (& self , id : & BenchmarkId , _ : & ReportContext) { self . text_overwrite () ; println ! ("Benchmarking {}: Complete (Analysis Disabled)" , id) ; } fn analysis (& self , id : & BenchmarkId , _ : & ReportContext) { self . text_overwrite () ; self . print_overwritable (format ! ("Benchmarking {}: Analyzing" , id)) ; } fn measurement_start (& self , id : & BenchmarkId , _ : & ReportContext , sample_count : u64 , estimate_ns : f64 , iter_count : u64 ,) { self . text_overwrite () ; let iter_string = if matches ! (self . verbosity , CliVerbosity :: Verbose) { format ! ("{} iterations" , iter_count) } else { format :: iter_count (iter_count) } ; self . print_overwritable (format ! ("Benchmarking {}: Collecting {} samples in estimated {} ({})" , id , sample_count , format :: time (estimate_ns) , iter_string)) ; } fn measurement_complete (& self , id : & BenchmarkId , _ : & ReportContext , meas : & MeasurementData < '_ > , formatter : & dyn ValueFormatter ,) { self . text_overwrite () ; let typical_estimate = & meas . absolute_estimates . typical () ; { let mut id = id . as_title () . to_owned () ; if id . len () > 23 { println ! ("{}" , self . green (& id)) ; id . clear () ; } let id_len = id . len () ; println ! ("{}{}time:   [{} {} {}]" , self . green (& id) , " " . repeat (24 - id_len) , self . faint (formatter . format_value (typical_estimate . confidence_interval . lower_bound)) , self . bold (formatter . format_value (typical_estimate . point_estimate)) , self . faint (formatter . format_value (typical_estimate . confidence_interval . upper_bound))) ; } if let Some (ref throughput) = meas . throughput { println ! ("{}thrpt:  [{} {} {}]" , " " . repeat (24) , self . faint (formatter . format_throughput (throughput , typical_estimate . confidence_interval . upper_bound)) , self . bold (formatter . format_throughput (throughput , typical_estimate . point_estimate)) , self . faint (formatter . format_throughput (throughput , typical_estimate . confidence_interval . lower_bound)) ,) ; } if ! matches ! (self . verbosity , CliVerbosity :: Quiet) { if let Some (ref comp) = meas . comparison { let different_mean = comp . p_value < comp . significance_threshold ; let mean_est = & comp . relative_estimates . mean ; let point_estimate = mean_est . point_estimate ; let mut point_estimate_str = format :: change (point_estimate , true) ; let to_thrpt_estimate = | ratio : f64 | 1.0 / (1.0 + ratio) - 1.0 ; let mut thrpt_point_estimate_str = format :: change (to_thrpt_estimate (point_estimate) , true) ; let explanation_str : String ; if ! different_mean { explanation_str = "No change in performance detected." . to_owned () ; } else { let comparison = compare_to_threshold (mean_est , comp . noise_threshold) ; match comparison { ComparisonResult :: Improved => { point_estimate_str = self . green (& self . bold (point_estimate_str)) ; thrpt_point_estimate_str = self . green (& self . bold (thrpt_point_estimate_str)) ; explanation_str = format ! ("Performance has {}." , self . green ("improved")) ; } ComparisonResult :: Regressed => { point_estimate_str = self . red (& self . bold (point_estimate_str)) ; thrpt_point_estimate_str = self . red (& self . bold (thrpt_point_estimate_str)) ; explanation_str = format ! ("Performance has {}." , self . red ("regressed")) ; } ComparisonResult :: NonSignificant => { explanation_str = "Change within noise threshold." . to_owned () ; } } } if meas . throughput . is_some () { println ! ("{}change:" , " " . repeat (17)) ; println ! ("{}time:   [{} {} {}] (p = {:.2} {} {:.2})" , " " . repeat (24) , self . faint (format :: change (mean_est . confidence_interval . lower_bound , true)) , point_estimate_str , self . faint (format :: change (mean_est . confidence_interval . upper_bound , true)) , comp . p_value , if different_mean { "<" } else { ">" } , comp . significance_threshold) ; println ! ("{}thrpt:  [{} {} {}]" , " " . repeat (24) , self . faint (format :: change (to_thrpt_estimate (mean_est . confidence_interval . upper_bound) , true)) , thrpt_point_estimate_str , self . faint (format :: change (to_thrpt_estimate (mean_est . confidence_interval . lower_bound) , true)) ,) ; } else { println ! ("{}change: [{} {} {}] (p = {:.2} {} {:.2})" , " " . repeat (24) , self . faint (format :: change (mean_est . confidence_interval . lower_bound , true)) , point_estimate_str , self . faint (format :: change (mean_est . confidence_interval . upper_bound , true)) , comp . p_value , if different_mean { "<" } else { ">" } , comp . significance_threshold) ; } println ! ("{}{}" , " " . repeat (24) , explanation_str) ; } } if ! matches ! (self . verbosity , CliVerbosity :: Quiet) { self . outliers (& meas . avg_times) ; } if matches ! (self . verbosity , CliVerbosity :: Verbose) { let format_short_estimate = | estimate : & Estimate | -> String { format ! ("[{} {}]" , formatter . format_value (estimate . confidence_interval . lower_bound) , formatter . format_value (estimate . confidence_interval . upper_bound)) } ; let data = & meas . data ; if let Some (slope_estimate) = meas . absolute_estimates . slope . as_ref () { println ! ("{:<7}{} {:<15}[{:0.7} {:0.7}]" , "slope" , format_short_estimate (slope_estimate) , "R^2" , Slope (slope_estimate . confidence_interval . lower_bound) . r_squared (data) , Slope (slope_estimate . confidence_interval . upper_bound) . r_squared (data) ,) ; } println ! ("{:<7}{} {:<15}{}" , "mean" , format_short_estimate (& meas . absolute_estimates . mean) , "std. dev." , format_short_estimate (& meas . absolute_estimates . std_dev) ,) ; println ! ("{:<7}{} {:<15}{}" , "median" , format_short_estimate (& meas . absolute_estimates . median) , "med. abs. dev." , format_short_estimate (& meas . absolute_estimates . median_abs_dev) ,) ; } } fn group_separator (& self) { println ! () ; } }
    };
}

